"""Security B: application and supply chain security, DLP, NAC, privileged access, email security, cloud security, zero trust access.

Mostly control-plane and policy products: they sit beside the request path, so they carry `security` + `platform` and no `cap`. The
exceptions are the products that really stand in the path of traffic (an email gateway, a ZTNA gateway): they are a gateway tier
with `replicas` and `cap`, and a single instance of them is a single point of failure for the flow they carry. A vault of
privileged credentials keeps state (`stateful` + `backup-required`); a provider's service is `saas` (trait `managed`).
"""
from forge import *

FUNCTIONS = {"security": [
    ("appsec", "Безопасность приложений и цепочки поставок", "Application and supply chain security", "bug-off"),
    ("dlp", "Защита от утечек (DLP)", "Data loss prevention (DLP)", "file-lock"),
    ("nac", "Контроль доступа к сети (NAC)", "Network access control (NAC)", "user-check"),
    ("pam", "Привилегированный доступ (PAM)", "Privileged access management (PAM)", "key-square"),
    ("email-security", "Защита почты", "Email security", "mail"),
    ("cloud-security", "Безопасность облаков (CSPM, CWPP)", "Cloud security (CSPM, CWPP)", "cloud-cog"),
    ("zero-trust", "Zero Trust доступ (ZTNA)", "Zero trust access (ZTNA)", "door-closed"),
]}
IAC = {"appsec": "security", "dlp": "security", "nac": "security", "pam": "security", "email-security": "security", "cloud-security": "saas", "zero-trust": "saas"}

STATE = ["stateful", "backup-required"]               # the product keeps its own data: a backup target must exist
APPSEC = T["security"] + ["appsec"]
DLP = T["security"] + ["dlp"]
NAC = T["security"] + ["nac"]
PAM = T["security"] + ["pam"]
MAIL = ["security", "gateway", "email-security"]      # stands in the mail flow: a gateway tier
CLOUD = T["security"] + ["cloud-security"]
ZTNA = ["security", "gateway", "zero-trust"]          # stands in the path of the users to the applications: a gateway tier

